3	== Specification/basic/trait-parameters.tex:313-514
4	
5	Object or functional declarations may include \KWD{where} clauses,
6	under the same restriction.
7	The following declaration of an \TYP{Empty} list is not allowed:
8	%(* Not allowed! *)
9	%object Empty extends List[\T\] where {T extends Object}
10	%  first() = throw Error
11	%  rest() = throw Error
12	%  cons(x) = Cons(x,self)
13	%  append(xs) = xs
14	%end
15	\begin{Fortress}
16	\(\mathtt{(*}\;\hbox{\rm  Not allowed! \unskip}\;\mathtt{*)}\)\\
17	\(\KWD{object} \TYP{Empty} \KWD{extends} \TYP{List}\llbracket{}T\rrbracket \KWD{where} \{T \KWD{extends} \TYP{Object}\}\)\\
18	{\tt~~}\pushtabs\=\+\(  \VAR{first}() = \;\KWD{throw} \TYP{Error}\)\\
19	\(  \VAR{rest}() = \;\KWD{throw} \TYP{Error}\)\\
20	\(  \VAR{cons}(x) = \TYP{Cons}(x,\KWD{self})\)\\
21	\(  \VAR{append}(\VAR{xs}) = \VAR{xs}\)\-\\\poptabs
22	\(\KWD{end}\)
23	\end{Fortress}
24	where \TYP{Cons} is declared in \secref{object-decls}.
25	Instead, the empty list is one object for each element type,
26	and each use writes the element type,
27	as in \EXP{\TYP{Empty}\llbracket\mathbb{Z}32\rrbracket}:
28	%object Empty[\T\] extends List[\T\]
29	%  first(): T = throw NotFound
30	%  rest(): List[\T\] = throw NotFound
31	%  cons(x: T): List[\T\] = Cons[\T\](x, self)
32	%  append(xs: List[\T\]): List[\T\] = xs
33	%end
34	\begin{Fortress}
35	\(\KWD{object}\:\TYP{Empty}\llbracket{}T\rrbracket \KWD{extends}\:\TYP{List}\llbracket{}T\rrbracket\)\\
36	{\tt~~}\pushtabs\=\+\(  \VAR{first}()\COLON T = \;\KWD{throw}\:\TYP{NotFound}\)\\
37	\(  \VAR{rest}()\COLON \TYP{List}\llbracket{}T\rrbracket = \;\KWD{throw}\:\TYP{NotFound}\)\\
38	\(  \VAR{cons}(x\COLON T)\COLON \TYP{List}\llbracket{}T\rrbracket = \TYP{Cons}\llbracket{}T\rrbracket(x, \KWD{self})\)\\
39	\(  \VAR{append}(\VAR{xs}\COLON \TYP{List}\llbracket{}T\rrbracket)\COLON \TYP{List}\llbracket{}T\rrbracket = \VAR{xs}\)\-\\\poptabs
40	\(\KWD{end}\)
41	\end{Fortress}
42	The library declares its empty collections and its empty optional value
43	(\secref{convenience-types}) the same way.
44	\revision{revival-empty}{The Working Draft of February 2011 gave the
45	declaration marked ``Not allowed'' as its example of a \KWD{where} clause on
46	an object. It makes \TYP{Empty} a \EXP{\TYP{List}\llbracket{}T\rrbracket} for
47	every \VAR{T} at once, which instantiation exclusion forbids.
48	The declaration after it is the library's own shape; it needs the element
49	type written at each use until the static arguments of a generic object can
50	be inferred.}
51	
