import java.util.*;
public class Below {
  // For samples whose stack holds the frame matching a[1], count the frame just below it (callee) and the top frame.
  public static void main(String[] a) throws Exception {
    Map<String,Integer> callee = new HashMap<>(), top = new HashMap<>(); long n = 0;
    try (RecordingFile rf = new RecordingFile(Path.of(a[0]))) {
      while (rf.hasMoreEvents()) {
        RecordedEvent e = rf.readEvent();
        if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
        RecordedStackTrace st = e.getStackTrace(); if (st == null) continue;
        List<RecordedFrame> fs = st.getFrames();
        for (int i = fs.size() - 1; i >= 0; i--) {
          String m = fs.get(i).getMethod().getType().getName() + "." + fs.get(i).getMethod().getName() + ":" + fs.get(i).getLineNumber();
          if (m.contains(a[1])) {
            n++;
            if (i > 0) { RecordedFrame c = fs.get(i-1); callee.merge(c.getMethod().getType().getName() + "." + c.getMethod().getName() + ":" + c.getLineNumber(), 1, Integer::sum); }
            RecordedFrame t = fs.get(0); top.merge(t.getMethod().getType().getName() + "." + t.getMethod().getName(), 1, Integer::sum);
            break;
          }
        }
      }
    }
    System.out.println("samples under " + a[1] + ": " + n);
    callee.entrySet().stream().sorted((x,y)->y.getValue()-x.getValue()).limit(12).forEach(x -> System.out.println("  callee " + x.getValue() + " " + x.getKey()));
    top.entrySet().stream().sorted((x,y)->y.getValue()-x.getValue()).limit(12).forEach(x -> System.out.println("  top " + x.getValue() + " " + x.getKey()));
  }
}
